import { tv, type VariantProps } from "@/lib/beton/tv";

/** Scramble, typewriter and counter share one plain typographic surface. */
export const textEffect = tv({
  base: "font-display font-black tracking-tight text-foreground tabular-nums",
  variants: {
    size: {
      sm: "text-h4",
      md: "text-h3",
      lg: "text-h2",
      xl: "text-h1",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const typewriter = tv({
  slots: {
    root: "font-display font-black tracking-tight text-foreground",
    caret: "ml-0.5 inline-block w-[0.6ch] bg-foreground align-baseline motion-safe:animate-blink",
  },
  variants: {
    size: {
      sm: { root: "text-h4", caret: "h-[1em]" },
      md: { root: "text-h3", caret: "h-[1em]" },
      lg: { root: "text-h2", caret: "h-[1em]" },
      xl: { root: "text-h1", caret: "h-[1em]" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const glitchText = tv({
  slots: {
    root: "relative inline-block font-display font-black tracking-tight text-foreground",
    layer: "pointer-events-none absolute inset-0 select-none",
    body: "relative",
    a: "text-primary motion-safe:animate-glitch-a motion-reduce:hidden",
    b: "text-danger motion-safe:animate-glitch-b motion-reduce:hidden",
  },
  variants: {
    size: {
      sm: { root: "text-h4" },
      md: { root: "text-h3" },
      lg: { root: "text-h2" },
      xl: { root: "text-h1" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type TextEffectVariants = VariantProps<typeof textEffect>;
export type TypewriterVariants = VariantProps<typeof typewriter>;
export type GlitchTextVariants = VariantProps<typeof glitchText>;

"use client";

import { typewriter, type TypewriterVariants } from "@/lib/beton/recipes/text-effects.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import { useEffect, useState, type ComponentProps } from "react";
import { useReducedMotion } from "@/lib/beton/use-reduced-motion";

export interface TypewriterProps
  extends Omit<ComponentProps<"span">, "children">, TypewriterVariants {
  /** The lines to type, one after another. */
  children: string | string[];
  /** Milliseconds per character. */
  speed?: number;
  /** How long a finished line stays before it is deleted. */
  pause?: number;
  /** Start again at the first line once the last one is done. */
  loop?: boolean;
  /** Show the blinking block after the text. */
  caret?: boolean;
}

/**
 * Words typed out one character at a time. The full text is always available
 * to screen readers, and reduced motion shows it at once.
 */
export function Typewriter({
  size = "md",
  children,
  speed = 60,
  pause = 1400,
  loop = true,
  caret = true,
  className,
  ...props
}: TypewriterProps) {
  const lines = Array.isArray(children) ? children : [children];
  const full = lines.join(". ");
  const reduced = useReducedMotion();
  const [index, setIndex] = useState(0);
  const [count, setCount] = useState(0);
  const [deleting, setDeleting] = useState(false);

  const line = lines[index % lines.length] ?? "";

  useEffect(() => {
    if (reduced) return;
    const done = count === line.length;
    if (done && !deleting) {
      const last = index === lines.length - 1;
      if (last && !loop) return;
      const timer = setTimeout(() => setDeleting(true), pause);
      return () => clearTimeout(timer);
    }
    if (deleting && count === 0) {
      setDeleting(false);
      setIndex((current) => (current + 1) % lines.length);
      return;
    }
    const timer = setTimeout(
      () => setCount((current) => current + (deleting ? -1 : 1)),
      deleting ? speed / 2 : speed,
    );
    return () => clearTimeout(timer);
  }, [count, deleting, index, line.length, lines.length, loop, pause, reduced, speed]);

  const styles = typewriter({ size });
  return (
    <span {...props} className={styles.root({ class: className })}>
      <span aria-hidden="true">{reduced ? line : line.slice(0, count)}</span>
      {caret && !reduced ? <span aria-hidden="true" className={styles.caret()} /> : null}
      <span className={visuallyHidden}>{full}</span>
    </span>
  );
}
